package meter_test

import (
	"errors"
	"fmt"
	"time"

	"github.com/descikazuyq/subscription-meter/meter"
)

// ExampleService_paymentReplay 演示“原样重报旧付款返回历史结果”以及如何
// 读取账单当前欠款。整个示例只使用 meter 的公开入口，并通过
// NewServiceWithClock 把当前时刻固定在一个已经结束的 UTC 自然月账期之后，
// 因此无论实际运行日期为何，输出都固定。
//
// 账户 acct-pay 的 2026-01 账单应付 1000 分（月费 1000、税额与用量均为
// 零），随后分两笔付清：p1 登记 400 分，p2 登记剩余 600 分。结清后再用
// p1 原样重报，返回的仍是 p1 首次登记完成时的结果——这不是本次调用时的
// 账单当前余额。
// ExampleService_paymentReplay is the English-titled mirror kept for
// tooling; 中文说明以本函数上方注释为准。
func ExampleService_paymentReplay() {
	// 把“当前时刻”固定在 2026-02-01 00:00 UTC：2026-01 账期恰好结束，
	// 可以立即为该月出账；示例不依赖运行当天的真实日期。
	const jan1st = "2026-01-01 00:00 UTC"
	period := meter.MonthOf(mustParseTime(jan1st))
	clock := func() time.Time { return mustParseTime("2026-02-01 00:00 UTC") }
	s := meter.NewServiceWithClock(clock)

	if err := s.CreateAccount("acct-pay"); err != nil {
		log.Fatal(err)
	}
	// 套餐月费恰好 1000 分，无超额、无税：账单 TotalDue 就是 1000 分。
	if err := s.CreatePlan(meter.Plan{
		ID:                 "plan1000",
		MonthlyFee:         1000,
		IncludedUnits:      0,
		OveragePrice:       0,
		TaxRateBasisPoints: 0,
